      "code_path": "crates/evm/src/eth/block.rs::execute_transaction_without_commit::L113-134",
      "proof_trace": "Block executor validates regular gas limit (L119-127) but completely omits blob gas limit validation. Blob gas is accumulated (L152-154) without any check against MAX_BLOB_GAS_PER_BLOCK, allowing blocks to exceed consensus-mandated blob gas limits.",
      "attack_scenario": "Attacker submits multiple blob transactions whose cumulative blob gas exceeds MAX_BLOB_GAS_PER_BLOCK. Block executor accepts all transactions, producing an invalid block that violates consensus rules and will be rejected by other nodes.",
      "checklist_id": "PROP-5a6a79d5-inv-008"
    },
    "text": "Blob transaction gas must not exceed remaining block blob gas limit.",
    "assertion": "forall tx, block: is_Blob(tx) => total_blob_gas(tx) <= MAX_BLOB_GAS - blob_gas_used",
    "covers": "SG-006",
    "severity": "MEDIUM",
    "type": "invariant"
  }
}

